<?php
/**
 * Work With Me and availability update, for ONE site at a time. Ryan, 2026-10-25: docs/inter-model/ThaiSolitude_WorkWithMe_Availability_Plan.md, "Getting our facts straight. Not disrupting the site. Again, go staging first.
 * We're using staging38 now."
 *
 * What it changes (WordPress's own storage; no files, no MU-plugin): EXACT replacements, listed in availability-content.php (generated by build-availability-update.py; read its header for the reasoning):
 *   - the WPCode snippet "CorporateBand" (the strip under the header): the plan's availability notice, plus Home in its page list, switching itself to "Now accepting" on 2026-11-01 (Pacific time);
 *   - the corporate page: two sentences (bookings begin November 1, 2026; events are scheduled around her work commitments);
 *   - Work With Me: two sentences (independent practice alongside employment; the "For clients" paragraph);
 *   - the Thai, Therapeutic and Deep Tissue pages: two FAQ answers each ("Where Do Sessions Take Place?" and "How Do I Book a Session?") that implied individual bookings now.
 * NOTHING ELSE changes: every old text must occur EXACTLY ONCE (ready) or every new text exactly once (applied); anything else stops the run, so edits made elsewhere in the meantime survive and are never overwritten.
 * The strip is PHP code that runs on every page it appears on, so its syntax is checked in memory (the PHP tokenizer) BEFORE anything is written.
 *
 * Allow-list: localhost:8090 and staging38. Live is NOT allowed: it is added only on Ryan's explicit go after staging38 is reviewed, and he starts the live run himself.
 *
 * Modes (first WP-CLI argument; run with --user=1):  <mode> [FILE]
 *   preflight    read-only: ready = every old text is there once and the snippet holds the old code; applied = every new text is there once and the snippet holds the new code; CHANGED = anything else (stop)
 *   apply        snapshot the four pages and the snippet, make every replacement, read everything back; put everything back if any read-back differs
 *   rollback     FILE = the before-snapshot: turn every new text back into the old (other edits made since are kept) and put the old strip code back
 * apply and rollback need WWM_BACKUP_DIR (an existing, writable absolute directory outside the web root). (WordPress also keeps its own revision of every page.)
 */

if ( ! defined( 'ABSPATH' ) || ! class_exists( 'WP_CLI' ) ) {
	exit( 'Run with WP-CLI.' );
}

$home = untrailingslashit( home_url() );
$host = (string) wp_parse_url( $home, PHP_URL_HOST ) . ( wp_parse_url( $home, PHP_URL_PORT ) ? ':' . wp_parse_url( $home, PHP_URL_PORT ) : '' );
if ( ! in_array( $host, array( 'localhost:8090', 'staging38.thaisolitude.com' ), true ) ) {
	WP_CLI::error( 'Refusing to run: ' . $home . ' is not an allowed target (localhost:8090 or staging38 only).' );
}
if ( 'astra' !== get_stylesheet() ) {
	WP_CLI::error( 'Active theme is not Astra.' );
}
if ( ! current_user_can( 'manage_options' ) || ! current_user_can( 'unfiltered_html' ) ) {
	WP_CLI::error( 'Run with --user=1 (an administrator) so WordPress does not filter the saved code.' );
}
if ( ! function_exists( 'wpcode' ) || ! class_exists( 'WPCode_Snippet' ) ) {
	WP_CLI::error( 'WPCode (insert-headers-and-footers) is not loaded.' );
}
$args = isset( $args ) && is_array( $args ) ? $args : array();
$mode = $args ? (string) $args[0] : 'preflight';
if ( ! in_array( $mode, array( 'preflight', 'apply', 'rollback' ), true ) ) {
	WP_CLI::error( 'Unknown mode: ' . $mode );
}

// ---- the reviewed content ------------------------------------------------------------------------------------------------------------------------
$data = is_file( __DIR__ . '/availability-content.php' ) ? require __DIR__ . '/availability-content.php' : null;
if ( ! is_array( $data ) || empty( $data['pairs'] ) || empty( $data['band_old'] ) || empty( $data['band_new'] ) || empty( $data['band_title'] ) ) {
	WP_CLI::error( 'availability-content.php is missing or incomplete (run build-availability-update.py).' );
}
$pairs     = $data['pairs'];
$band_old  = (string) $data['band_old'];
$band_new  = (string) $data['band_new'];
$band_name = (string) $data['band_title'];
foreach ( $pairs as $p ) {
	if ( empty( $p['slug'] ) || empty( $p['old'] ) || empty( $p['new'] ) || $p['old'] === $p['new'] || false !== strpos( $p['new'], $p['old'] ) ) {
		WP_CLI::error( 'Internal error: a replacement is not what was reviewed: ' . ( $p['label'] ?? '?' ) );
	}
}

// ---- wording checks on everything that becomes visible (the whole house list applies; "studio" is on it, so the notice says "location") ------------------------------
foreach ( $pairs as $p ) {
	$text = html_entity_decode( wp_strip_all_tags( $p['new'] ), ENT_QUOTES, 'UTF-8' );
	$band = null;
	foreach ( array( 'proof', 'measurable', 'effective', 'pain relief', 'pain management', 'sciatica', 'headache', 'chronic', 'adhesion', 'corrective', 'accelerate', 'restore', 'nervous system', 'circulation', 'anxiety', 'cancer', 'neurological', 'disabilit', 'prevention', 'lasting', 'long-term wellness', 'overall health', 'real results', 'studio', 'cure', 'treat', 'diagnos', 'inflammation', 'detox', 'guarantee', 'relieve', 'relief', 'portland-area', 'portland metro' ) as $bad ) {
		if ( false !== stripos( $text, $bad ) ) {
			WP_CLI::error( 'The new text of "' . $p['label'] . '" contains a term this site must not use: ' . $bad );
		}
	}
	if ( preg_match( '/\bheal(s|ed|ing|er)?\b/i', $text ) || preg_match( '/\b(we|our|us|ours)\b/i', $text ) ) {
		WP_CLI::error( 'The new text of "' . $p['label'] . '" contains heal/healing or we/our/us, which this site must not use.' );
	}
}
// the strip's visible words are the string literals of the code; check them with the same list
preg_match_all( "/'([^'\\\\]*(?:\\\\.[^'\\\\]*)*)'/", $band_new, $lits );
$band_text = html_entity_decode( wp_strip_all_tags( implode( ' ', $lits[1] ) ), ENT_QUOTES, 'UTF-8' );
foreach ( array( 'studio', 'relief', 'treat', 'cure', 'guarantee', 'heal', 'diagnos', 'chronic', 'effective', 'portland-area', 'portland metro' ) as $bad ) {
	if ( false !== stripos( $band_text, $bad ) ) {
		WP_CLI::error( 'The strip contains a term this site must not use: ' . $bad );
	}
}
if ( preg_match( '/\b(we|our|us|ours)\b/i', $band_text ) ) {
	WP_CLI::error( 'The strip contains we/our/us, which this site must not use.' );
}
// the strip is PHP that runs on page views: it must parse (checked in memory, nothing is run or written)
try {
	token_get_all( "<?php\n" . $band_new, TOKEN_PARSE );
	token_get_all( "<?php\n" . $band_old, TOKEN_PARSE );
} catch ( \ParseError $e ) {
	WP_CLI::error( 'The strip code does not parse: ' . $e->getMessage() . ' (line ' . $e->getLine() . '). Nothing was changed.' );
}

// ---- the site as it is ------------------------------------------------------------------------------------------------------------------------------
$slugs = array();
foreach ( $pairs as $p ) {
	$slugs[ $p['slug'] ] = true;
}
$slugs = array_keys( $slugs );

$read = function () use ( $pairs, $slugs, $band_old, $band_new, $band_name ) {
	$r = array( 'items' => array(), 'pages' => array() );
	foreach ( $slugs as $slug ) {
		$pg = get_page_by_path( $slug );
		$r['pages'][ $slug ] = ( $pg && 'publish' === $pg->post_status ) ? $pg : null;
	}
	foreach ( $pairs as $i => $p ) {
		$pg = $r['pages'][ $p['slug'] ];
		if ( ! $pg ) {
			$r['items'][ $i ] = 'CHANGED';
			continue;
		}
		$c     = (string) $pg->post_content;
		$n_old = substr_count( $c, $p['old'] );
		$n_new = substr_count( $c, $p['new'] );
		$r['items'][ $i ] = ( 1 === $n_old && 0 === $n_new ) ? 'ready' : ( ( 0 === $n_old && 1 === $n_new ) ? 'applied' : 'CHANGED' );
	}
	$found = get_posts( array( 'post_type' => 'wpcode', 'post_status' => 'any', 'title' => $band_name, 'numberposts' => -1, 'suppress_filters' => true ) );
	$r['snippet_posts'] = $found;
	if ( 1 !== count( $found ) || 'publish' !== $found[0]->post_status ) {
		$r['snippet'] = 'CHANGED';
	} elseif ( trim( (string) $found[0]->post_content ) === trim( $band_old ) ) {
		$r['snippet'] = 'ready';
	} elseif ( trim( (string) $found[0]->post_content ) === trim( $band_new ) ) {
		$r['snippet'] = 'applied';
	} else {
		$r['snippet'] = 'CHANGED';
	}
	$all = array_merge( array_values( $r['items'] ), array( $r['snippet'] ) );
	if ( count( $all ) === count( array_filter( $all, function ( $s ) { return 'ready' === $s; } ) ) ) {
		$r['state'] = 'ready';
	} elseif ( count( $all ) === count( array_filter( $all, function ( $s ) { return 'applied' === $s; } ) ) ) {
		$r['state'] = 'applied';
	} else {
		$r['state'] = 'CHANGED';
	}
	$bad = array();
	foreach ( $r['items'] as $i => $s ) {
		if ( 'CHANGED' === $s ) {
			$bad[] = $pairs[ $i ]['label'];
		}
	}
	$r['report'] = sprintf( 'replacements ready=%d applied=%d changed=%d; strip snippet=%s%s', count( array_keys( $r['items'], 'ready', true ) ), count( array_keys( $r['items'], 'applied', true ) ),
		count( $bad ), $r['snippet'], $bad ? ' [CHANGED: ' . implode( '; ', $bad ) . ']' : '' );
	return $r;
};
$now    = $read();
$state  = $now['state'];
$report = sprintf( 'host=%s state=%s %s', $home, $state, $now['report'] );

if ( 'preflight' === $mode ) {
	if ( 'CHANGED' === $state ) {
		WP_CLI::error( 'Not every old text is there exactly once (or every new text exactly once), or a page or the strip snippet is not as reviewed; stop and review. ' . $report );
	}
	WP_CLI::success( 'Preflight passed; nothing changed. ' . $report );
	return;
}

$backup_dir = getenv( 'WWM_BACKUP_DIR' );
if ( ! $backup_dir || '/' !== $backup_dir[0] || ! is_dir( $backup_dir ) || ! is_writable( $backup_dir ) || 0 === strpos( realpath( $backup_dir ), realpath( ABSPATH ) ) ) {
	WP_CLI::error( 'WWM_BACKUP_DIR must be an existing, writable absolute directory outside the web root.' );
}
$refresh = function () {
	if ( isset( wpcode()->cache ) && method_exists( wpcode()->cache, 'cache_all_loaded_snippets' ) ) {
		wpcode()->cache->cache_all_loaded_snippets();
	}
};
$set_content = function ( $post_id, $content ) {
	return wp_update_post( wp_slash( array( 'ID' => (int) $post_id, 'post_content' => $content ) ), true );
};

if ( 'apply' === $mode ) {
	if ( 'CHANGED' === $state ) {
		WP_CLI::error( 'The state is not the reviewed one; nothing was changed. ' . $report );
	}
	if ( 'applied' === $state ) {
		WP_CLI::success( 'Nothing to do: already applied. ' . $report );
		return;
	}
	$snap = array( 'created' => gmdate( 'c' ), 'home' => $home, 'pages' => array(), 'snippet_id' => (int) $now['snippet_posts'][0]->ID, 'snippet_old_code' => (string) $now['snippet_posts'][0]->post_content );
	foreach ( $slugs as $slug ) {
		$pg = $now['pages'][ $slug ];
		$snap['pages'][ $slug ] = array( 'id' => (int) $pg->ID, 'old_sha256' => hash( 'sha256', (string) $pg->post_content ), 'old_content' => (string) $pg->post_content );
	}
	$snap['snippet_old_sha256'] = hash( 'sha256', $snap['snippet_old_code'] );
	$file = rtrim( $backup_dir, '/' ) . '/availability-update-before-' . gmdate( 'Ymd-His' ) . '.json';
	$ok   = false !== file_put_contents( $file, wp_json_encode( $snap ) );
	if ( ! $ok || filesize( $file ) < 1000 ) {
		WP_CLI::error( 'Could not write the before-snapshot; nothing was changed.' );
	}
	chmod( $file, 0600 );

	$undo = function () use ( $snap, $set_content, $refresh ) {
		foreach ( $snap['pages'] as $pg ) {
			if ( (string) get_post_field( 'post_content', (int) $pg['id'] ) !== $pg['old_content'] ) {
				$set_content( (int) $pg['id'], $pg['old_content'] );
			}
		}
		if ( (string) get_post_field( 'post_content', (int) $snap['snippet_id'] ) !== $snap['snippet_old_code'] ) {
			wp_update_post( wp_slash( array( 'ID' => (int) $snap['snippet_id'], 'post_content' => $snap['snippet_old_code'] ) ), true );
		}
		$refresh();
	};
	$fail = function ( $why ) use ( $undo, $read ) {
		$undo();
		$check = $read();
		WP_CLI::error( $why . ' Everything was put back (state now: ' . $check['state'] . ').' );
	};

	// 1. the four pages (every replacement once each)
	foreach ( $slugs as $slug ) {
		$content = $snap['pages'][ $slug ]['old_content'];
		foreach ( $pairs as $p ) {
			if ( $p['slug'] !== $slug ) {
				continue;
			}
			$content = str_replace( $p['old'], $p['new'], $content, $count );
			if ( 1 !== $count ) {
				$fail( 'A replacement did not match exactly once (' . $p['label'] . ').' );
			}
		}
		$res = $set_content( $snap['pages'][ $slug ]['id'], $content );
		if ( is_wp_error( $res ) || ! $res || (string) get_post_field( 'post_content', $snap['pages'][ $slug ]['id'] ) !== $content ) {
			$fail( 'The ' . $slug . ' page did not save exactly as written.' );
		}
	}
	// 2. the strip
	$res = wp_update_post( wp_slash( array( 'ID' => $snap['snippet_id'], 'post_content' => $band_new ) ), true );
	$refresh();
	$sp = get_post( $snap['snippet_id'] );
	if ( is_wp_error( $res ) || ! $sp || 'publish' !== $sp->post_status || trim( (string) $sp->post_content ) !== trim( $band_new ) ) {
		$fail( 'The strip snippet did not save exactly as written.' );
	}
	$after = $read();
	if ( 'applied' !== $after['state'] ) {
		$fail( 'Read-back differed from what was written (' . $after['report'] . ').' );
	}
	WP_CLI::success( 'Applied ' . count( $pairs ) . ' replacements on ' . count( $slugs ) . ' pages and updated the strip snippet #' . $snap['snippet_id'] . '. Before-snapshot: ' . $file );
	return;
}

// ---- rollback FILE ---------------------------------------------------------------------------------------------------------
$file = isset( $args[1] ) ? (string) $args[1] : '';
$snap = $file && is_file( $file ) ? json_decode( (string) file_get_contents( $file ), true ) : null;
if ( ! is_array( $snap ) || ( $snap['home'] ?? '' ) !== $home || empty( $snap['pages'] ) || empty( $snap['snippet_id'] ) || ! isset( $snap['snippet_old_code'] ) || hash( 'sha256', (string) $snap['snippet_old_code'] ) !== ( $snap['snippet_old_sha256'] ?? '' ) ) {
	WP_CLI::error( 'Snapshot is missing, incomplete (the apply may not have finished), damaged, or from another site.' );
}
foreach ( $snap['pages'] as $slug => $pg ) {
	if ( empty( $pg['old_content'] ) || hash( 'sha256', (string) $pg['old_content'] ) !== ( $pg['old_sha256'] ?? '' ) ) {
		WP_CLI::error( 'Snapshot is damaged (the ' . $slug . ' page).' );
	}
}
if ( 'applied' !== $state || (int) $now['snippet_posts'][0]->ID !== (int) $snap['snippet_id'] ) {
	WP_CLI::success( 'Nothing to roll back: the pages and the strip do not hold the new text exactly once each. ' . $report );
	return;
}
foreach ( $slugs as $slug ) {
	$content = (string) $now['pages'][ $slug ]->post_content;
	foreach ( $pairs as $p ) {
		if ( $p['slug'] === $slug ) {
			$content = str_replace( $p['new'], $p['old'], $content );   // only these texts go back: edits made elsewhere since the apply are kept
		}
	}
	$set_content( (int) $now['pages'][ $slug ]->ID, $content );
}
wp_update_post( wp_slash( array( 'ID' => (int) $snap['snippet_id'], 'post_content' => (string) $snap['snippet_old_code'] ) ), true );
$refresh();
$check = $read();
if ( 'ready' !== $check['state'] ) {
	WP_CLI::error( 'Rollback did not return to the original state (now: ' . $check['report'] . '); stop and inspect.' );
}
$same = true;
foreach ( $snap['pages'] as $slug => $pg ) {
	$same = $same && hash( 'sha256', (string) get_post_field( 'post_content', (int) $pg['id'] ) ) === $pg['old_sha256'];
}
$same_sn = hash( 'sha256', (string) get_post_field( 'post_content', (int) $snap['snippet_id'] ) ) === $snap['snippet_old_sha256'];
WP_CLI::success( 'Rollback done: the old texts and the old strip code are back (pages ' . ( $same ? 'byte-identical to the snapshot' : 'differ from the snapshot elsewhere: edited after the apply, and those edits were kept' ) . '; snippet ' . ( $same_sn ? 'byte-identical' : 'differs' ) . ').' );

// ref: ./build-availability-update.py, ./availability-content.php — the reviewed text; ../corporate/install-corporate-massage.php — the pattern this follows; ../deep-tissue/install-deep-tissue-copy.php — the exact-replacement pattern
